NS = "gov-"  # run namespace prefix; each case uses NS + case_id + worker id.


def case(
    cid: str,
    title: str,
    suite: str,
    layer: str,
    reqs: list[str],
    facets: list[str],
    basis: str,
    gate: str,
    priority: str,
    risk: str,
    fixtures: list[str],
    pre: list[str],
    inp: dict,
    steps: list[tuple[str, str]],
    asserts: list[str],
    forbid: list[str],
    evid: list[str],
    clean: list[str],
    auto: str,
    prereq: list[str] | None = None,
    env: str = "offline",
    pair: str | None = None,
    refs: list[str] | None = None,
) -> dict:
    """Build one case record. ``steps`` are (action, expected) pairs, in order."""
    rec = {
        "id": cid,
        "title": title,
        "suite": suite,
        "layer": layer,
        "environment": env,
        "priority": priority,
        "gate": gate,
        "requirements": list(reqs),
        "facets": list(facets),
        "basis": basis,
        "references": list(refs) if refs else [SRS, IMPL08],
        "risk": risk,
        "fixtures": list(fixtures),
        "preconditions": list(pre),
        "inputs": dict(inp),
        "steps": [{"action": a, "expected": e} for a, e in steps],
        "assertions": list(asserts),
        "forbidden": list(forbid),
        "evidence": list(evid),
        "cleanup": list(clean),
        "automation": auto,
        "prerequisites": list(prereq) if prereq else [],
    }
    if pair:
        rec["pair"] = pair
    return rec


