_APV_PRE = [
    "Namespace " + NS + "apv-<case_id>-<worker_id>; approval queue seeded from fixtures/offline/governance.json.",
    "Operator identities and roles resolved from the fixture operator registry; every decision goes through POST /api/v1/approvals/{id}/decision, the only approval route.",
]
_APV_STEPS_TAIL = "Re-read the approval record and the immutable audit rows to confirm the decision was recorded once with the operator identity."

