        ["entity:Evidence", "entity:Action", "stage:EVIDENCE"], "baseline", "P0", "critical",
        "An outbound message or order exists with no audit trail, so disputes, chargebacks and regulatory queries cannot be answered from platform records.",
        [GOV_FX, CONSENT_FX],
